package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * How a claim's live figures (the rate step and the late charge) round to cents: half up when the
 * claim is dated before the sheet's policy date (none: the sheet's today), else half to even. A
 * correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    private Rounding() {}

    /** The date a claim rounds by: a correction's corrected claim's date (from {@code datesByNumber}), else its own. */
    public static LocalDate basisOf(Claim claim, Map<String, LocalDate> datesByNumber) {
        if (claim.getCorrects() != null) {
            LocalDate corrected = datesByNumber.get(claim.getCorrects());
            if (corrected != null) return corrected;
        }
        return claim.getDate();
    }

    /** The rounding of a claim rounding by the given date. */
    public static RoundingMode of(LocalDate basis, LocalDate policyDate, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return policy != null && basis.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The dates of the numbered claims, by number. */
    public static Map<String, LocalDate> datesByNumber(List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim c : claims) {
            if (c.getNumber() != null) dates.put(c.getNumber(), c.getDate());
        }
        return dates;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.function.Function;

/**
 * The late charge on an overdue claim, worked out per 30-day boundary: for each full 30 days past its
 * due-by plus its grace days (those of its person's grade on its date, in force on its date; 0 when none), the
 * late percent in force on that boundary date (the due-by plus the grace plus 30, 60, 90 ... days) of its
 * figure (the rate figure bound by a statement, else its rate figure, with no floor) plus the charges of the
 * boundaries before it (compounding), rounded to cents like its due ({@link Rounding}), and the charges added up; a boundary whose percent is 0.00 adds nothing. A
 * correction has none. It is never bound by a statement; settling freezes it into the settled due.
 */
public final class LateCharge {

    /** The days in each step of the charge. */
    private static final int STEP_DAYS = 30;

    private LateCharge() {}

    /**
     * Overdue: OPEN (or PENDING), not deferred, with its due-by (fixed when it was added) plus its grace days
     * before the sheet's today.
     */
    public static boolean isOverdue(Claim claim, LocalDate today, int graceDays) {
        return claim.getStatus().isOpen() && today != null && lateFrom(claim, graceDays).isBefore(today)
                && !claim.isDeferredOn(today);
    }

    /**
     * The charge on the claim with the given figure (null: none) as of today, with the late percent in
     * force on each date from {@code latePctOn}; zero when not overdue or a correction.
     */
    public static BigDecimal of(Claim claim, BigDecimal figure, LocalDate today, int graceDays,
            Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
        if (figure == null || claim.isCorrection() || !isOverdue(claim, today, graceDays)) return BigDecimal.ZERO.setScale(2);
        return charge(claim, figure, today, graceDays, latePctOn, rounding);
    }

    /**
     * The figure with the charge it would have on top were the claim open now, whatever its status; null
     * when the figure is.
     */
    public static BigDecimal withChargeAsOpen(Claim claim, BigDecimal figure, LocalDate today, int graceDays,
            Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
        if (figure == null || claim.isCorrection() || today == null || !lateFrom(claim, graceDays).isBefore(today)) {
            return figure;
        }
        return figure.add(charge(claim, figure, today, graceDays, latePctOn, rounding));
    }

    /** The figure with its charge added on top; null when the figure is. */
    public static BigDecimal withCharge(Claim claim, BigDecimal figure, LocalDate today, int graceDays,
            Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
        return figure == null ? null : figure.add(of(claim, figure, today, graceDays, latePctOn, rounding));
    }

    /** The date past which the claim is late: its due-by plus its grace days; the due-by shown is unchanged. */
    private static LocalDate lateFrom(Claim claim, int graceDays) {
        return claim.getDueBy().plusDays(graceDays);
    }

    /**
     * The charges of each 30-day boundary past the due-by plus the grace up to today, each on the figure plus the
     * charges before it, added up.
     */
    private static BigDecimal charge(Claim claim, BigDecimal figure, LocalDate today, int graceDays,
            Function<LocalDate, BigDecimal> latePctOn, RoundingMode rounding) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (LocalDate boundary = lateFrom(claim, graceDays).plusDays(STEP_DAYS); !boundary.isAfter(today);
                boundary = boundary.plusDays(STEP_DAYS)) {
            BigDecimal pct = latePctOn.apply(boundary);
            if (pct == null || pct.signum() == 0) continue;
            total = total.add(figure.add(total).multiply(pct).movePointLeft(2).setScale(2, rounding));
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a DRAFT,
 * OPEN or PENDING claim can be voided (VOID). A clerk's settling above the clerk limit makes it
 * PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again). A steward
 * may void a SETTLED claim shortly after its settlement ({@link ClaimService}); VOID is final.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /**
     * Whether a claim in this status may move to {@code next} by opening, settling or voiding it; a
     * PENDING claim leaves for SETTLED or OPEN only by a steward's approval or rejection.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like it. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }
}

