50	 * A steward can re-date an OPEN or PENDING claim ({@link #redate}).
51	 */
52	@Service
53	public class ClaimService {
54	
55	    /** How many days after its settlement a steward may still void a SETTLED claim. */
56	    static final int VOID_SETTLED_DAYS = 7;
57	
58	    private final ClaimRepository claims;
59	    private final PersonRepository people;
60	    private final RateService rates;
