113	     * a reference already on the sheet is refused.
114	     */
115	    @Transactional
116	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
117	            String corrects, String ref, List<String> tagged) {
118	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
119	        RollupService.Snapshot before = rollup.snapshot(sheetId);
120	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
121	        LocalDate on = dateOrEntryDate(sheetId, date);
122	        int terms = termsOf(sheetId, person, on);
123	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
124	        refuseIfClosed(sheetId, dueBy);
125	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
126	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
127	        refuseIfRefUsed(sheetId, null, ref);
128	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy, terms);
129	        draft.setCorrects(corrects);
130	        draft.setRef(ref);
131	        draft.setTags(tagged);
132	        draft.setLateEntry(periods.softClosedOn(sheetId, dueBy));
133	        Claim claim = claims.saveAndFlush(draft);
134	        logStatus(sheetId, user, person, claim);
135	        claim = claims.saveAndFlush(claim);
136	        record("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
137	                (claim.getRef() != null ? " ref=" + claim.getRef() : "")
138	                + (claim.getTags().isEmpty() ? "" : " tags=" + String.join(",", claim.getTags())));
139	        keepTags(sheetId, claim);
140	        if (claim.isLateEntry()) record("LATE_ENTRY", sheetId, user, person, claim);
141	        rollup.recordChanges(sheetId, user, before);
