182	        // Locking the sheet first, so two users opening the same claim's editor at once take turns.
183	        sheets.lockForNumbering(sheetId);
184	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
185	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusRefusedException();
186	        refuseIfClosed(sheetId, claim.getDueBy());
