224	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason) {
225	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
226	        // once no other open on the sheet is under way; a refusal rolls the number back.
227	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
228	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
229	        String action = switch (next) {
230	            case OPEN -> "open";
231	            case SETTLED -> "settle";
232	            case VOID -> "void";
233	            default -> throw new ClaimStatusRefusedException();
234	        };
235	        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
236	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
237	        if (voidingSettled) refuseVoidOfSettled(sheetId, user, claim);
238	        else if (!claim.getStatus().canBecome(next)) {
239	            throw new ClaimStatusRefusedException();
240	        }
241	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
242	            throw new ClaimDeferredException();
243	        }
244	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
245	            throw new ClaimSettledByOpenerException();
246	        }
247	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
248	        // Settling freezes the late charge of the moment into the settled due.
249	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
250	        if (next == ClaimStatus.SETTLED) refuseUnproved(sheetId, person, claim, settling);
251	        if (next == ClaimStatus.OPEN) refuseUnnoted(sheetId, claim, chargedFigureOf(sheetId, person, claim));
252	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
253	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonForVoid(sheetId, reason) : null;
254	        RollupService.Snapshot before = rollup.snapshot(sheetId);
255	        refuseIfClosed(sheetId, claim.getDueBy());
256	        switch (next) {
257	            case OPEN -> {
258	                number(numbering, claim);
259	                claim.setOpenedBy(user.strip());
260	            }
261	            case SETTLED -> {
262	                claim.setSettledDue(settling);
263	                claim.setSettleBatch(null);
264	            }
265	            case PENDING -> claim.setSettleBatch(null);
266	            case VOID -> claim.setVoidReason(voidReason);
267	            default -> {}
268	        }
269	        claim.setStatus(next);
270	        logStatus(sheetId, user, person, claim);
271	        Claim saved = claims.saveAndFlush(claim);
272	        String event = switch (next) {
273	            case OPEN -> "CLAIM_OPENED";
274	            case PENDING -> "CLAIM_PENDING";
275	            case SETTLED -> "CLAIM_SETTLED";
276	            case VOID -> "CLAIM_VOIDED";
277	            case DRAFT -> throw new IllegalStateException();
278	        };
279	        String due = next == ClaimStatus.SETTLED
280	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
281	                : voidingSettled ? " reversed=" + figureText(saved.getSettledDue())
282	                : "";
283	        if (voidReason != null) due += " reason=" + voidReason;
284	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
285	        if (next == ClaimStatus.SETTLED) notifyWatchers(sheetId, user, person, saved);
286	        rollup.recordChanges(sheetId, user, before);
287	        return saved;
288	    }
