328	    /**
329	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
330	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
331	     * late charge as of today). Refused for anyone
332	     * else, a claim in any other status, or one due inside a closed period.
333	     */
334	    @Transactional
335	    public Claim resettle(String sheetId, String user, Long id) {
336	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
339	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
340	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
341	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
342	        refuseIfClosed(sheetId, claim.getDueBy());
343	        BigDecimal old = claim.getSettledDue();
344	        BigDecimal figure = floored(sheetId, claim, LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim),
345	                sheets.today(sheetId), graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d),
346	                roundingOf(sheetId, claim)));
347	        claim.setSettledDue(figure);
348	        logStatus(sheetId, user, person, claim);
349	        Claim saved = claims.saveAndFlush(claim);
350	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
351	                " old=" + figureText(old) + " new=" + figureText(figure));
352	        notifyWatchers(sheetId, user, person, saved);
353	        rollup.recordChanges(sheetId, user, before);
354	        return saved;
355	    }
