357	    /**
358	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
359	     * statement stays bound; its period, which follows its due-by, stays too. While the sheet numbers by
360	     * period and the claim was numbered within another period, it takes the next number of its due-by's
361	     * period, its old number never given again. Refused for anyone else, a claim in any other status, one
362	     * due inside a closed period, or a new date after its person's retirement date.
363	     */
364	    @Transactional
365	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
366	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
367	        Sheet numbering = sheets.lockForNumbering(sheetId);
368	        RollupService.Snapshot before = rollup.snapshot(sheetId);
369	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
370	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
371	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
372	        refuseIfClosed(sheetId, claim.getDueBy());
373	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
374	        if (!person.mayClaimOn(date)) throw new PersonRetiredException();
375	        LocalDate old = claim.getDate();
376	        String oldPeriod = claim.getNumberPeriod() != null ? claim.getNumberPeriod() : periodOn(sheetId, claim.getDueBy());
377	        claim.setDate(date);
378	        if (numbering.numbersByPeriod() && !oldPeriod.equals(periodOn(sheetId, claim.getDueBy()))) {
379	            if (claim.getNumberPeriod() != null) {
380	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
381	            }
382	            number(numbering, claim);
383	        }
384	        Claim saved = claims.saveAndFlush(claim);
385	        record("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
386	        rollup.recordChanges(sheetId, user, before);
387	        return saved;
388	    }
