390	    /**
391	     * Refuse voiding a SETTLED claim unless by a steward within {@value #VOID_SETTLED_DAYS} days of its
392	     * settlement (its status log's last SETTLED date) by the sheet's today.
393	     */
394	    private void refuseVoidOfSettled(String sheetId, String user, Claim claim) {
395	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
396	        LocalDate settled = claim.settledOn();
397	        LocalDate today = sheets.today(sheetId);
398	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
399	            throw new ClaimVoidWindowException();
400	        }
401	    }
