427	    /**
428	     * Reassign a claim by the rules above; a bulk move ({@code bulk}) takes a claim already its new
429	     * person's as moved to them again rather than refusing it.
430	     */
431	    @Transactional
432	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean bulk) {
433	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
434	        RollupService.Snapshot before = rollup.snapshot(sheetId);
435	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
436	        ClaimStatus status = claim.getStatus();
437	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
438	        if (!settings.mayDo(sheetId, user, "reassign")) throw new ClaimNotPermittedException();
439	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
440	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
441	        if (!bulk && from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
442	        refuseIfClosed(sheetId, claim.getDueBy());
443	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
444	        claim.unstate(sheets.today(sheetId));
445	        claim.moveTo(to.getId(), claims.nextListed());
446	        Claim saved = claims.saveAndFlush(claim);
447	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
448	                " from=" + from.getName() + " to=" + to.getName());
449	        rollup.recordChanges(sheetId, user, before);
450	        return saved;
451	    }
