456	    /**
457	     * Split an amount (more than 0.00 and less than its amount) off an OPEN claim, by a user whose role may
458	     * open a claim. The claim keeps the rest of its amount and loses any figure a statement bound it to; the
459	     * new claim is OPEN with the split-off amount, the same date and note, the sheet's next number, opened
460	     * by the user, with its due-by fixed now from the terms in force on the date, and names the original's
461	     * number as split from, a late entry when its due-by falls in a soft-closed period. Refused for a claim
462	     * not OPEN, a deferred one, or one due inside a closed period (judged by the original alone).
463	     */
464	    @Transactional
465	    public Split split(String sheetId, String user, Long id, BigDecimal amount) {
466	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
467	        Sheet numbering = sheets.lockForNumbering(sheetId);
468	        RollupService.Snapshot before = rollup.snapshot(sheetId);
469	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
470	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
471	        if (claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimDeferredException();
472	        if (!settings.mayDo(sheetId, user, "open")) throw new ClaimNotPermittedException();
473	        refuseIfClosed(sheetId, claim.getDueBy());
474	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitRefusedException();
475	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
476	        LocalDate on = claim.getDate();
477	        claim.setAmount(claim.getAmount().subtract(amount));
478	        claim.unstate(sheets.today(sheetId));
479	        Claim original = claims.saveAndFlush(claim);
480	        int terms = termsOf(sheetId, person, on);
481	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
482	        Claim split = new Claim(sheetId, person.getId(), amount, on, original.getNote(), dueBy, terms);
483	        split.setSplitFrom(original.getNumber());
484	        split.setTags(original.getTags());
485	        split.setLateEntry(periods.softClosedOn(sheetId, dueBy));
486	        number(numbering, split);
487	        split.setOpenedBy(user.strip());
488	        split.setEditedBy(original.getEditedBy());
489	        split.setStatus(ClaimStatus.OPEN);
490	        split = claims.saveAndFlush(split);
491	        logStatus(sheetId, user, person, split);
492	        split = claims.saveAndFlush(split);
493	        record("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
494	        record("CLAIM_OPENED", sheetId, user, person, split);
495	        rollup.recordChanges(sheetId, user, before);
496	        return new Split(original, split);
497	    }
