499	    /**
500	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
501	     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a
502	     * claim that is not OPEN, a date not after today, or a claim due inside a closed period.
503	     */
504	    @Transactional
505	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
506	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
507	        RollupService.Snapshot before = rollup.snapshot(sheetId);
508	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
509	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
510	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferDateException();
511	        refuseIfClosed(sheetId, claim.getDueBy());
512	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
513	        claim.deferUntil(until, sheets.today(sheetId));
514	        Claim saved = claims.saveAndFlush(claim);
515	        record("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber(), " until=" + until);
516	        rollup.recordChanges(sheetId, user, before);
517	        return saved;
518	    }
519	
520	    /**
521	     * Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim, or one due inside a closed period.
522	     */
523	    @Transactional
524	    public Claim addProof(String sheetId, String user, Long id) {
525	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
526	        RollupService.Snapshot before = rollup.snapshot(sheetId);
527	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
528	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
529	            throw new ClaimStatusRefusedException();
530	        }
531	        refuseIfClosed(sheetId, claim.getDueBy());
532	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
533	        claim.addProof();
534	        Claim saved = claims.saveAndFlush(claim);
535	        record("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
536	        rollup.recordChanges(sheetId, user, before);
537	        return saved;
538	    }
539	
540	    /** Comment on a claim: the comment is kept with the user and the sheet's today, in any status. */
541	    @Transactional
542	    public Claim comment(String sheetId, String user, Long id, String text) {
543	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
544	        RollupService.Snapshot before = rollup.snapshot(sheetId);
545	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
546	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
547	        claim.comment(user.strip(), sheets.today(sheetId), text);
548	        Claim saved = claims.saveAndFlush(claim);
549	        record("COMMENT_ADDED", sheetId, user, person, saved, saved.getNumber(), " text=" + text);
550	        rollup.recordChanges(sheetId, user, before);
551	        return saved;
552	    }
553	
554	    /**
555	     * Remind an OPEN or PENDING claim: a REMIND line is written and the claim is reminded on the sheet's
556	     * today. Refused for a claim in any other status, or one already reminded on the sheet's today.
557	     */
558	    @Transactional
559	    public Claim remind(String sheetId, String user, Long id) {
560	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
561	        RollupService.Snapshot before = rollup.snapshot(sheetId);
562	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
563	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
564	        LocalDate today = sheets.today(sheetId);
565	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
566	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
567	        claim.remind(today);
568	        Claim saved = claims.saveAndFlush(claim);
569	        record("REMIND", sheetId, user, person, saved);
570	        rollup.recordChanges(sheetId, user, before);
571	        return saved;
572	    }
573	
574	    /**
575	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force on
576	     * its date (its person's grade's then when set, else the sheet's); a due of n/a is within any, and no
577	     * threshold means none is needed.
578	     */
579	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
580	        if (claim.getProofs() > 0 || due == null) return;
581	        BigDecimal threshold = settings.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
582	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
583	    }
584	
585	    /**
586	     * Refuse opening a claim with an empty note whose due is above the note threshold in force on its date;
587	     * a due of n/a is within any, and no threshold means no note is needed.
588	     */
589	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
590	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
591	        BigDecimal threshold = settings.noteThresholdOn(sheetId, claim.getDate());
592	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
593	    }
594	
595	    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
596	    private Claim pendingForSteward(String sheetId, String user, Long id) {
597	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
598	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
599	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
600	        return claim;
601	    }
602	
603	    /**
604	     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
605	     * within the period its due-by falls in (in no period: the next in the sheet's X sequence).
606	     */
607	    private void number(Sheet sheet, Claim claim) {
608	        if (!sheet.numbersByPeriod()) {
609	            claim.setNumber(sheet.nextClaimNumber());
610	            return;
611	        }
612	        String period = periodOn(sheet.getId(), claim.getDueBy());
613	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
614	    }
615	
616	    /**
617	     * The terms a claim of the person dated on the date is fixed with: their own terms, else their grade's
618	     * then. Its due-by is the terms-th business day after its date (skipping weekends and the sheet's holidays).
619	     */
620	    private int termsOf(String sheetId, Person person, LocalDate on) {
621	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(on), on);
622	    }
623	
624	    /** The name of the sheet's period the date falls in; empty when in none. */
625	    private String periodOn(String sheetId, LocalDate date) {
626	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
627	                .filter(p -> p.contains(date))
628	                .map(Period::getName)
629	                .findFirst().orElse("");
630	    }
631	
632	    /**
633	     * A claim's figure now: the due fixed when it was settled, else the rate figure bound by its person's
634	     * last statement, else its rate figure (no floor, no charge); null when it has none.
635	     */
636	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
637	        if (claim.getSettledDue() != null) return claim.getSettledDue();
638	        if (claim.isBound()) return claim.getStatedDue();
639	        return dueOf(sheetId, person, claim);
640	    }
641	
642	    /**
643	     * A claim's due now: the greater of the floor in force on its date and its figure with the late
644	     * charge on top while it is overdue (a correction: neither); a settled due as fixed; null when it
645	     * has none. A statement binds the figure, never the charge nor the floor.
646	     */
647	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
648	        return charged(sheetId, person, claim, figureOf(sheetId, person, claim));
649	    }
650	
651	    /** What a rate preview finds: how many claims' dues would change, and by how much in all. */
652	    public record RatePreview(int count, BigDecimal diff) {}
653	
654	    /**
655	     * How many OPEN and PENDING claims of people on the grade (the one in force on the claim's date) would show
656	     * a different due were the percent the grade's rate on every date, and the sum of new minus current dues
657	     * (a due of n/a counts as 0). A claim bound by a statement does not change. Nothing is stored.
658	     */
659	    @Transactional(readOnly = true)
660	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
661	        int count = 0;
662	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
663	        java.util.Map<Long, Person> byId = new java.util.HashMap<>();
664	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) byId.put(p.getId(), p);
665	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
666	            if (!claim.getStatus().isOpen() || claim.isBound()) continue;
667	            Person person = byId.get(claim.getPersonId());
668	            if (person == null || !grade.equals(person.gradeOn(claim.getDate()))) continue;
669	            BigDecimal current = chargedFigureOf(sheetId, person, claim);
670	            BigDecimal figure = claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
671	            BigDecimal next = charged(sheetId, person, claim, figure);
672	            BigDecimal was = current == null ? BigDecimal.ZERO.setScale(2) : current;
673	            BigDecimal now = next == null ? BigDecimal.ZERO.setScale(2) : next;
674	            if (current == null || now.compareTo(was) != 0) {
675	                count++;
676	                diff = diff.add(now.subtract(was));
677	            }
678	        }
679	        return new RatePreview(count, diff.setScale(2));
680	    }
681	
682	    /** The claim's due with the figure given: floored, with its late charge while overdue; a settled due as fixed. */
683	    private BigDecimal charged(String sheetId, Person person, Claim claim, BigDecimal figure) {
684	        if (claim.getSettledDue() != null) return claim.getSettledDue();
685	        return floored(sheetId, claim, LateCharge.withCharge(claim, figure, sheets.today(sheetId),
686	                graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim)));
687	    }
688	
689	    /** The grace days of the person's grade on the claim's date, in force on it; 0 when none. */
690	    private int graceOf(String sheetId, Person person, Claim claim) {
691	        return settings.graceOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
692	    }
693	
694	    /** The due at least the sheet's floor in force on the claim's date, unless a correction; null when none. */
695	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
696	        if (due == null || claim.isCorrection()) return due;
697	        return due.max(settings.floorOn(sheetId, claim.getDate()));
698	    }
699	
700	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
701	    private RoundingMode roundingOf(String sheetId, Claim claim) {
702	        LocalDate basis = Rounding.basisOf(claim,
703	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
704	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
705	    }
706	
707	    /**
708	     * A claim's rate figure: its amount times the rate on its date of its person's grade in force on it, rounded to
709	     * cents as {@link Rounding} has it, with no floor; null with no rate.
710	     */
711	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
712	        RoundingMode rounding = roundingOf(sheetId, claim);
713	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
714	                .map(Rate::getPct)
715	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
716	                .orElse(null);
717	    }
718	
719	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
720	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
721	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
722	    }
723	
724	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
725	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
726	    }
727	
728	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
729	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
730	            String extra) {
731	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
732	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
733	                + (number != null ? " number=" + number : "") + extra);
734	    }
735	
736	    /** Keep each of the claim's tags among those ever used on the sheet. */
737	    private void keepTags(String sheetId, Claim claim) {
738	        for (String tag : claim.getTags()) {
739	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) tags.save(new ClaimTag(sheetId, tag));
740	        }
741	    }
742	
743	    /** Refuse a reference (null: none) that a claim on the sheet other than this one (null: any) already carries. */
744	    private void refuseIfRefUsed(String sheetId, Long self, String ref) {
745	        if (ref == null) return;
746	        claims.findBySheetIdAndRefKey(sheetId, Claim.refKeyOf(ref))
747	                .filter(other -> !other.getId().equals(self))
748	                .ifPresent(other -> { throw new DuplicateClaimRefException(); });
749	    }
750	
751	    /**
752	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
753	     * one but is not a correction.
754	     */
755	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
756	        if (amount.signum() >= 0) {
757	            if (corrects != null) throw new CorrectionRefusedException();
758	            return;
759	        }
760	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
761	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
762	        if (!settled) throw new CorrectionRefusedException();
763	    }
764	
765	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
766	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
767	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
768	        BigDecimal limit = settings.clerkLimit(sheetId);
769	        return limit != null && due != null && due.compareTo(limit) > 0;
770	    }
771	
772	    /** Refuse a change to a claim whose due-by falls inside a closed period; the caller holds the sheet's lock. */
773	    private void refuseIfClosed(String sheetId, LocalDate date) {
774	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
775	    }
776	
777	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
778	        return date != null ? date : sheets.today(sheetId);
779	    }
780	
781	    /** A new claim's date: the one given, else the entry date while set, else the sheet's today. */
782	    private LocalDate dateOrEntryDate(String sheetId, LocalDate date) {
783	        if (date != null) return date;
784	        LocalDate entryDate = settings.entryDate(sheetId);
785	        return entryDate != null ? entryDate : sheets.today(sheetId);
786	    }
787	}
