package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
 * sheet's claimed-total and due-total, each person's at most the sheet's cap in force today; a claim's floor is the one in force on its date, its late percent the one in force on each 30-day boundary; an overdue claim's due has its {@link LateCharge} on top. A change takes a {@link #snapshot} before it alters
 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
 * lines, a ROLLUP line for each person whose figures (overdue-total included) moved (in the order
 * they were added) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** A person's figures; a null due-total is n/a; the overdue-total is the dues of their overdue claims. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(dueTotal, other.dueTotal)
                    && overdueTotal.compareTo(other.overdueTotal) == 0;
        }
    }

    /** The sheet's figures at a moment: each person's, by id in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Locks the sheet until the caller's transaction ends, so no other
     * change on the sheet moves the figures between this snapshot and the one after the change.
     */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findForUpdate(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        LocalDate policyDate = sheet == null ? null : sheet.getPolicyDate();
        Map<String, List<Rate>> ratesByGrade = new LinkedHashMap<>();
        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)) {
            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
        }
        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(all);
        for (Claim claim : all) {
            if (claim.getStatus().counts()) {
                claimsByPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean fixed = false;
            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
                if (!person.counts(claim, today)) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                RoundingMode rounding = Rounding.of(Rounding.basisOf(claim, datesByNumber), policyDate, today);
                // the floor in force on the claim's date, the late percent in force on each 30-day boundary
                BigDecimal floor = sheet == null ? zero() : sheet.floorOn(claim.getDate());
                // and the grace days of their grade on the claim's date, in force on it
                int grace = sheet == null ? 0 : sheet.graceOn(grade, claim.getDate());
                BigDecimal figure = LateCharge.withCharge(claim,
                        figureOf(claim, ratesByGrade.getOrDefault(grade, List.of()), rounding), today, grace,
                        d -> sheet == null ? zero() : sheet.latePctOn(d), rounding);
                // the floor last, over the figure and its charge; a settled due is frozen, a correction has none
                if (figure != null && claim.getSettledDue() == null && !claim.isCorrection()) figure = figure.max(floor);
                // a due under a grade they had on its date but not today counts like a fixed one
                if (figure != null && today != null && !grade.equals(person.gradeOn(today))) fixed = true;
                // and so does a due under a rate that is not the one in force today
                if (figure != null && today != null && !Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()),
                        claim.getDate()).equals(Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()), today))) fixed = true;
                if (figure != null) due = due.add(figure);
                if (figure != null && LateCharge.isOverdue(claim, today, grace)) overdue = overdue.add(figure);
            }
            // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
            // due, nor a due under another grade they had on its date or under a rate not in force today.
            boolean rated = today != null
                    && pctOn(ratesByGrade.getOrDefault(person.gradeOn(today), List.of()), today) != null;
            BigDecimal personDue = fixed || rated ? due : null;
            if (sheet != null) personDue = sheet.capped(personDue);
            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) dues.add(personDue);
            overdues.add(overdue);
        }
        return new Snapshot(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
        if (figures.size() < 3) return sum;
        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
        return sum.subtract(max).subtract(min);
    }

    /** Audit, once the transaction commits, a SNAPSHOT line of each person's due-total in {@code snapshot}, in the order they were added. */
    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
        String by = " sheet=" + sheetId + " by=" + user.strip();
        for (Figures figures : snapshot.people().values()) {
            audit.recordOnCommit("SNAPSHOT" + by + " name=" + figures.name()
                    + " due-total=" + (figures.dueTotal() == null ? "n/a" : money(figures.dueTotal())));
        }
    }

    /** Audit, once the transaction commits, how the sheet's figures moved since {@code before}. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        String by = " sheet=" + sheetId + " by=" + user.strip();
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.sameAs(before.people().get(e.getKey()))) continue;
            audit.recordOnCommit("ROLLUP" + by + " person=" + now.name() + " claimed=" + money(now.claimed())
                    + " due-total=" + (now.dueTotal() == null ? "n/a" : money(now.dueTotal()))
                    + " overdue-total=" + money(now.overdueTotal()));
        }
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0
                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
            audit.recordOnCommit("TOTALS" + by + " claimed-total=" + money(after.claimedTotal())
                    + " due-total=" + money(after.dueTotal())
                    + " overdue-total=" + money(after.overdueTotal()));
        }
    }

    /**
     * A claim's figure: its settled due, else its stated rate figure, else its rate figure (no floor),
     * rounded as given; null when it has none.
     */
    private static BigDecimal figureOf(Claim claim, List<Rate> rates, RoundingMode rounding) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isBound()) return claim.getStatedDue();
        BigDecimal pct = pctOn(rates, claim.getDate());
        if (pct == null) return null;
        return claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding);
    }

    /** Of one grade's rates, the percent in force on the date, or null. */
    private static BigDecimal pctOn(List<Rate> rates, LocalDate date) {
        return Rate.inForce(rates, date)
                .map(Rate::getPct)
                .orElse(null);
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String money(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OrderBy;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/**
 * A person on a sheet, with a name and a grade (A, B or C). The name is kept without surrounding
 * spaces and is unique on the sheet without regard to case (by its {@link #keyOf key}). A person
 * given a retirement date is retired at once, whatever the date; none of their claims may be dated
 * after it, and from the day the sheet's today reaches it their open claims, unless bound by a
 * statement, leave the live totals as a hold's do. A person may have several holds over time, each from a from-date to an optional to-date. The grade is dated: the first one
 * given is in force from the beginning of time, and each later one from its from-date. A person may have
 * their own terms in days, which their claims' due-by takes ahead of their grade's and the sheet's.
 */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "grade", nullable = false)
    private String grade;

    /** The grades recorded after the first, by the date each is in force from. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "grade", nullable = false)
    private Map<LocalDate, String> datedGrades = new TreeMap<>();

    /** Each grade recorded after the first, oldest first, with the sheet's today it was recorded on. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade_log", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "seq")
    private List<PersonGradeLine> gradeLog = new ArrayList<>();

    /** The sheet's today when they were added; null when added before this was kept. */
    @Column(name = "added_on", updatable = false)
    private LocalDate addedOn;

    /** The sheet's today when their retirement date was last set; null while not retired, or set before this was kept. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** Their own terms in days, ahead of their grade's and the sheet's; null: none. */
    @Column(name = "terms")
    private Integer terms;

    /** Their contact, without surrounding spaces and lower-cased; null: none. */
    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds, earliest from-date first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    @OrderBy("fromDate ASC, toDate ASC")
    private List<PersonHold> holds = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {}

    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
        this.sheetId = sheetId;
        setName(name);
        this.grade = grade;
        this.addedOn = addedOn;
    }

    /** The key a name is compared by for uniqueness: without surrounding spaces, lower-cased. */
    public static String keyOf(String name) {
        return name.strip().toLowerCase(Locale.ROOT);
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public void setName(String name) {
        this.name = name.strip();
        this.nameKey = keyOf(name);
    }

    /** The first grade they were given, in force from the beginning of time. */
    public String getGrade() { return grade; }

    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> on = new TreeMap<>(datedGrades).floorEntry(date);
        return on == null ? grade : on.getValue();
    }

    /** Record the grade from the date on the sheet's today, in place of any recorded from the same date. */
    public void setGradeFrom(LocalDate from, String grade, LocalDate on) {
        datedGrades.put(from, grade);
        gradeLog.add(new PersonGradeLine(from, grade, on));
    }

    /**
     * The grade in force on the date as recorded by the end of the as-of date: of the grades recorded while
     * the sheet's today was on or before it, the one with the latest from-date on or before the date.
     */
    public String gradeOn(LocalDate date, LocalDate asOf) {
        TreeMap<LocalDate, String> then = new TreeMap<>();
        for (PersonGradeLine line : gradeLog) if (line.recordedBy(asOf)) then.put(line.getFromDate(), line.getGrade());
        Map.Entry<LocalDate, String> on = then.floorEntry(date);
        return on == null ? grade : on.getValue();
    }

    /** The sheet's today when they were added; null when added before this was kept. */
    public LocalDate getAddedOn() { return addedOn; }

    /** Whether they were on the sheet at the end of the date: added while its today was on or before it. */
    public boolean existedAt(LocalDate date) { return addedOn == null || !addedOn.isAfter(date); }

    /** The grades recorded after the first, by the date each is in force from, earliest first. */
    public Map<LocalDate, String> getDatedGrades() { return new TreeMap<>(datedGrades); }

    /** Their own terms in days, or null when they have none. */
    public Integer getTerms() { return terms; }

    public void setTerms(Integer terms) { this.terms = terms; }

    /** Their contact, or null when they have none. */
    public String getContact() { return contact; }

    public void setContact(String contact) { this.contact = contactOf(contact); }

    /** A contact as it is stored: without surrounding spaces, lower-cased; blank or null: none. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) return null;
        return contact.strip().toLowerCase(Locale.ROOT);
    }

    /** The date they are retired from, or null while not retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }

    /** Retire them from the date, on the sheet's today. */
    public void retireFrom(LocalDate retiredFrom, LocalDate on) {
        this.retiredFrom = retiredFrom;
        this.retiredOn = on;
    }

    public boolean isRetired() { return retiredFrom != null; }

    /** Whether a claim of theirs may be dated on the date: not after their retirement date. */
    public boolean mayClaimOn(LocalDate date) { return retiredFrom == null || !date.isAfter(retiredFrom); }

    /** Whether they have any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }

    /** Their holds, earliest from-date first. */
    public List<PersonHold> getHolds() { return List.copyOf(holds); }

    public void addHold(PersonHold hold) { holds.add(hold); }

    /** Whether the date falls within any of their holds. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.contains(date)); }

    /**
     * Whether the date falls within any of their holds put on while the sheet's today was on or before the
     * as-of date.
     */
    public boolean heldOn(LocalDate date, LocalDate asOf) {
        return holds.stream().anyMatch(h -> h.putOnBy(asOf) && h.contains(date));
    }

    /** Whether, as it stood at the end of the date, they were retired by it: retired then, from on or before it. */
    public boolean retiredAt(LocalDate date) {
        return retiredOn(date) && (retiredOn == null || !retiredOn.isAfter(date));
    }

    /** Whether their retirement date is reached on the date (the date on or after it). */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }

    /** Whether an open claim of theirs is kept out of the live totals: dated within a hold, or retired by the sheet's today. */
    private boolean keptOut(Claim claim, LocalDate today) { return heldOn(claim.getDate()) || retiredOn(today); }

    /**
     * Whether a claim of theirs counts in the live totals: it counts by its status, unless it is open
     * (OPEN or PENDING), dated within a hold or theirs once their retirement date is reached on the
     * sheet's today, and not bound by a statement, or deferred on the sheet's today.
     */
    public boolean counts(Claim claim, LocalDate today) {
        if (!claim.getStatus().counts() || claim.isDeferredOn(today)) return false;
        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
    }

    /**
     * Whether a claim of theirs counts for a period ending on the date: by the status it had at the end
     * of that date, less a deferred one and one still open now (OPEN or PENDING) dated within a hold, or
     * theirs once retired on the sheet's today, and not bound, as the live rules say: a claim since settled or voided is no longer kept out by a hold.
     */
    public boolean countsAt(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        if (at == null || !at.counts() || claim.isDeferredOn(today)) return false;
        return !claim.getStatus().isOpen() || claim.isBound() || !keptOut(claim, today);
    }

    /**
     * Whether they are active on the date: they have an open claim (OPEN or PENDING) that counts, dated
     * within the 30 days up to and including it.
     */
    public boolean activeOn(Iterable<Claim> claims, LocalDate today) {
        if (today == null) return false;
        LocalDate since = today.minusDays(29);
        for (Claim claim : claims) {
            if (!getId().equals(claim.getPersonId()) || !claim.getStatus().isOpen() || !counts(claim, today)) continue;
            if (!claim.getDate().isBefore(since) && !claim.getDate().isAfter(today)) return true;
        }
        return false;
    }

    /** Moved on by each save; an edit is refused unless made from the current version. */
    public long getVersion() { return version; }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person from its from-date (null: the beginning of time) to its to-date (null: open-ended), both included. */
@Embeddable
public class PersonHold {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    /** The sheet's today when it was put on; null when put on before this was kept. */
    @Column(name = "set_on")
    private LocalDate setOn;

    protected PersonHold() {}

    public PersonHold(LocalDate fromDate, LocalDate toDate, LocalDate setOn) {
        this.fromDate = fromDate;
        this.toDate = toDate;
        this.setOn = setOn;
    }

    public LocalDate getFromDate() { return fromDate; }

    public LocalDate getToDate() { return toDate; }

    /** Whether it was put on while the sheet's today was on or before the date. */
    public boolean putOnBy(LocalDate date) { return setOn == null || !setOn.isAfter(date); }

    /** Whether the date falls within the hold. */
    public boolean contains(LocalDate date) {
        return (fromDate == null || !date.isBefore(fromDate)) && (toDate == null || !date.isAfter(toDate));
    }
}

