  if (this.pctOf(gradeToday) === null && !counted.some(fixed)) return null;
  return counted.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs), graceOn) ?? 0), 0);
}
}

